/**
 * @function safeText
 * @description Converts unknown values into stable display text without inventing business data.
 * @param {*} value - Candidate value.
 * @param {string} fallback - Fallback display value.
 * @returns {string} Safe display text.
 * @collaboration Keeps CRM chrome readable while preserving source-empty states.
 */
function safeText(value, fallback = '—') {
  if (value === null || value === undefined) return fallback;
  const text = String(value).trim();
  return text || fallback;
}

/**
 * @function getStoredValue
 * @description Reads localStorage safely for non-secret UI identity hints.
 * @param {string} key - Storage key.
 * @param {string} fallback - Fallback value.
 * @returns {string} Stored value or fallback.
 * @collaboration Allows CRM to hydrate operator and tenant labels without requiring fragile global dependencies.
 */
function getStoredValue(key, fallback = '') {
  try {
    if (typeof window === 'undefined') return fallback;
    return window.localStorage.getItem(key) || fallback;
  } catch {
    return fallback;
  }
}

/**
 * @function readStoredJson
 * @description Reads JSON from localStorage safely.
 * @param {string} key - Storage key.
 * @returns {Object} Parsed object or empty object.
 * @collaboration Lets CRM consume existing auth context cache without crashing restricted browsers.
 */
function readStoredJson(key) {
  try {
    const raw = getStoredValue(key, '');
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

/**
 * @function buildInitials
 * @description Builds stable initials for identity fallback.
 * @param {string} value - Candidate name.
 * @returns {string} Initials.
 * @collaboration Keeps operator chrome stable when profile images are unavailable.
 */
function buildInitials(value = '') {
  const parts = String(value || '').trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return 'WK';
  return parts.slice(0, 2).map(part => part.charAt(0).toUpperCase()).join('');
}

/**
 * @function formatMoney
 * @description Formats numeric CRM value as South African Rand without inventing value.
 * @param {*} value - Candidate numeric value.
 * @returns {string} Money display.
 * @collaboration Keeps pipeline metrics aligned with Wilsy OS South African operating context.
 */
function formatMoney(value) {
  const numeric = Number(value || 0);
  return `R ${numeric.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}`;
}

/**
 * @function toNumber
 * @description Converts unknown numeric input into a safe number.
 * @param {*} value - Candidate numeric value.
 * @returns {number} Safe number.
 * @collaboration Protects pipeline calculations from partial source payloads.
 */
function toNumber(value) {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : 0;
}

/**
 * @function normalizeRecord
 * @description Normalizes one CRM record from any backend shape into dashboard-safe fields.
 * @param {Object} record - Source record.
 * @param {string} collection - CRM collection id.
 * @returns {Object} Normalized record.
 * @collaboration Allows CRM API routes to evolve without forcing the visual shell to duplicate data mapping.
 */
function normalizeRecord(record = {}, collection = 'records') {
  const id = record._id || record.id || record.uuid || record.recordId || `${collection}-${Math.random().toString(36).slice(2)}`;
  const value = toNumber(record.value || record.amount || record.dealValue || record.weightedValue || record.totalValue);
  const stage = safeText(record.stage || record.pipelineStage || record.status, 'Unstaged');

  return {
    id,
    collection,
    name: safeText(record.name || record.fullName || record.title || record.subject || record.companyName || record.accountName, 'Unnamed source record'),
    company: safeText(record.company || record.companyName || record.account || record.accountName || record.organization, '—'),
    email: safeText(record.email || record.primaryEmail || record.contactEmail, '—'),
    phone: safeText(record.phone || record.mobile || record.telephone || record.primaryPhone, '—'),
    owner: safeText(record.owner || record.ownerName || record.assignedTo || record.createdBy, '—'),
    status: safeText(record.status || record.sourceStatus || record.state || record.readiness, 'Source received'),
    stage,
    value,
    type: safeText(record.type || record.category || record.kind, collection),
    industry: safeText(record.industry || record.sector || record.market, '—'),
    dueDate: safeText(record.dueDate || record.date || record.meetingDate || record.scheduledFor, '—'),
    source: safeText(record.source || record.sourceSystem || record.connector || record.origin, 'Wilsy CRM API'),
    raw: record
  };
}

/**
 * @function normalizeCollectionPayload
 * @description Converts a backend payload into a normalized CRM record array.
 * @param {*} payload - Backend response payload.
 * @param {string} collection - CRM collection id.
 * @returns {Array<Object>} Normalized collection.
 * @collaboration Makes CRM source ingestion tolerant of Express, Mongoose, and service-layer response envelopes.
 */
function normalizeCollectionPayload(payload, collection) {
  const candidates = [
    payload?.data,
    payload?.records,
    payload?.items,
    payload?.results,
    payload?.[collection],
    payload
  ];

  const list = candidates.find(candidate => Array.isArray(candidate)) || [];
  return list.map(record => normalizeRecord(record, collection));
}

/**
 * @function buildAuthHeaders
 * @description Builds browser-safe API headers for CRM source requests.
 * @param {string} tenantId - Active tenant id.
 * @returns {Object} Headers.
 * @collaboration Keeps CRM API calls aligned with Wilsy OS tenant guard expectations.
 */
function buildAuthHeaders(tenantId) {
  const token = getStoredValue('token', '') || getStoredValue('authToken', '') || getStoredValue('wilsyAuthToken', '');
  const headers = {
    'Content-Type': 'application/json',
    'X-Tenant-Id': tenantId || 'MASTER',
    'X-Wilsy-Tenant-ID': tenantId || 'MASTER'
  };

  if (token) headers.Authorization = `Bearer ${token}`;
  return headers;
}

/**
 * @function fetchCrmCollection
 * @description Fetches one CRM collection from the live backend.
 * @param {string} collection - CRM collection id.
 * @param {string} tenantId - Active tenant id.
 * @param {AbortSignal} signal - Abort signal.
 * @returns {Promise<Object>} Source result.
 * @collaboration Keeps the dashboard source-led and avoids fake customer records.
 */
async function fetchCrmCollection(collection, tenantId, signal) {
  const endpoint = CRM_ENDPOINTS[collection];
  if (!endpoint) {
    return { collection, ok: false, records: [], error: 'Endpoint not configured' };
  }

  try {
    const response = await fetch(`${API_BASE}${endpoint}`, {
      method: 'GET',
      headers: buildAuthHeaders(tenantId),
      signal
    });

    if (!response.ok) {
      return {
        collection,
        ok: false,
        records: [],
        status: response.status,
        error: `HTTP ${response.status}`
      };
    }

    const payload = await response.json();
    return {
      collection,
      ok: true,
      records: normalizeCollectionPayload(payload, collection),
      status: response.status,
      error: null
    };
  } catch (error) {
    if (error?.name === 'AbortError') {
      return { collection, ok: false, records: [], aborted: true, error: 'Aborted' };
    }

    return {
      collection,
      ok: false,
      records: [],
      error: error?.message || 'Source request failed'
    };
  }
}

/**
 * @function createEmptySnapshot
 * @description Builds a zero-record CRM snapshot.
 * @returns {Object} Empty snapshot.
 * @collaboration Gives the dashboard a source-honest baseline before backend hydration completes.
 */
function createEmptySnapshot() {
  return {
    leads: [],
    contacts: [],
    accounts: [],
    deals: [],
    tasks: [],
    meetings: [],
    evidence: [],
    connectors: [],
    sourcePosture: {
      connected: 0,
      total: Object.keys(CRM_ENDPOINTS).length,
      errors: [],
      loading: false,
      lastSync: null
    }
  };
}

/**
 * @function calculateReadinessScore
 * @description Calculates CRM readiness from connected sources and captured evidence.
 * @param {Object} snapshot - CRM snapshot.
 * @returns {number} Readiness percentage.
 * @collaboration Produces an evidence-led score without hardcoded demo values.
 */
function calculateReadinessScore(snapshot) {
  const totalSources = snapshot.sourcePosture.total || Object.keys(CRM_ENDPOINTS).length;
  const connectedRatio = totalSources ? snapshot.sourcePosture.connected / totalSources : 0;
  const dataAnchors = [
    snapshot.leads.length > 0,
    snapshot.contacts.length > 0,
    snapshot.accounts.length > 0,
    snapshot.deals.length > 0,
    snapshot.evidence.length > 0
  ].filter(Boolean).length / 5;

  return Math.round(Math.min(100, ((connectedRatio * 70) + (dataAnchors * 30))));
}

/**
 * @function buildCrmSnapshot
 * @description Builds the final CRM snapshot from source results.
 * @param {Array<Object>} results - Source results.
 * @returns {Object} CRM snapshot.
 * @collaboration Centralizes CRM evidence posture so all dashboard panels share one truth.
 */
function buildCrmSnapshot(results = []) {
  const snapshot = createEmptySnapshot();
  const errors = [];

  results.forEach(result => {
    if (!result || !result.collection) return;
    snapshot[result.collection] = Array.isArray(result.records) ? result.records : [];

    if (result.ok) {
      snapshot.sourcePosture.connected += 1;
    } else if (!result.aborted) {
      errors.push({
        collection: result.collection,
        error: result.error || 'Unavailable source',
        status: result.status || null
      });
    }
  });

  snapshot.sourcePosture.errors = errors;
  snapshot.sourcePosture.lastSync = new Date().toISOString();
  return snapshot;
}

/**
 * @function buildPipelineStages
 * @description Builds pipeline stage cards from live deal records.
 * @param {Array<Object>} deals - Normalized deal records.
 * @returns {Array<Object>} Stage metrics.
 * @collaboration Keeps pipeline cockpit grounded in source deals only.
 */
function buildPipelineStages(deals = []) {
  return PIPELINE_STAGES.map(stage => {
    const stageDeals = deals.filter(deal => deal.stage.toLowerCase() === stage.toLowerCase());
    const value = stageDeals.reduce((sum, deal) => sum + toNumber(deal.value), 0);

    return {
      stage,
      count: stageDeals.length,
      value
    };
  });
}

/**
