                          return <td key={`${record.id}-${column}`}>{safeText(valueMap[key], '—')}</td>;
                        })}
                      </tr>
                    )) : (
                      <tr>
                        <td colSpan={(CRM_RECORD_COLUMNS[activeWorkspace] || CRM_RECORD_COLUMNS.leads).length}>
                          <div className={styles.emptyState}>
                            <Database size={28} />
                            <strong>No matching records.</strong>
                            <p>{loading ? 'Synchronising CRM source routes.' : 'No source records were returned for this workspace.'}</p>
                          </div>
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </section>
          )}
        </main>

        <footer className={styles.sovereignFooter} aria-label="CRM source posture">
          <span>{tenantIdentity.name}</span>
          <span>
            {snapshot.sourcePosture.connected} / {snapshot.sourcePosture.total} source routes {loading ? 'syncing' : 'checked'}
          </span>
        </footer>
      </section>

      <WilsyAccountCommandCenter
        isOpen={accountSettingsOpen}
        onClose={() => setAccountSettingsOpen(false)}
      />
    </div>
  );
}

export default CRMDashboard;

