function compactWilsySkinDoctrineR45(value = '') {
  return String(value || '')
    .replace(/\s+/g, ' ')
    .replace(/skin for /gi, 'skin for ')
    .replace(/tenants,/gi, 'tenants,')
    .trim();
}


